string s = "abcba";
bool isPalindrome = true;
int left = 0, right = s.length() - 1;
while (left < right) {
    if (s[left] != s[right]) {
        isPalindrome = false;
        break;
    }
    left++; right--;
}
cout << (isPalindrome ? "回文" : "非回文") << endl;

string s = "Hello World";
int vowels = 0, consonants = 0;
for (char c : s) {
    if (isalpha(c)) {
        c = tolower(c);
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') vowels++;
        else consonants++;
    }
}
cout << "元音: " << vowels << ", 辅音: " << consonants << endl;

