string s = "abcabcbb";
unordered_map<char, int> charMap;
int maxLen = 0, left = 0;
for (int right = 0; right < s.length(); right++) {
    if (charMap.count(s[right])) {
        left = max(left, charMap[s[right]] + 1);
    }
    charMap[s[right]] = right;
    maxLen = max(maxLen, right - left + 1);
}
cout << maxLen << endl;

